-- Запись выпуска: 4-П на весь период заказа техники на объект.
--
-- Решение — docs/adr/0207-vehicle-request-day-batch.md, план —
-- docs/vehicle-request-day-batch-plan.md. Схему этот выпуск меняет одной миграцией 0339
-- (новый вид операции day_batch); остальное — контракты, дверь пачки, портал и сверки соседей.
--
-- `seq = 109`, И ЭТО ПЕРВЫЙ НЕЗАНЯТЫЙ. Номер спрошен у РЕПОЗИТОРИЯ, а не у базы: часть
-- закоммиченных выпусков может быть не накатана, и max(seq) в базе врёт в меньшую сторону.
-- Лента идёт до 108 (0338_releases_copy_any_status.sql).
--
-- ОБРАТИМОСТЬ: строка ленты, DELETE FROM app_releases WHERE seq = 109.

INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  109, '0.1.98.0207', '2026-09-23', 'Путевые листы 4-П на весь период заказа техники', '{207}',
  '[
    {"kind":"feature","text":"При переводе заказа техники на объект в работу появилась галочка «Выписать 4-П на весь период»: диспетчер называет водителя, и портал на каждый день срока сам заводит рейс назначенной машины и выписывает по нему путевой лист. Та же кнопка есть в карточке заявки, на вкладке «Дни работ», — ею добирают дни после продления срока"},
    {"kind":"feature","text":"Дни работ и дневные 4-П теперь ведут у любого заказа техники на объект, а не только у линейного типа ТС: какой технике нужна дневная бумага, решает диспетчер по заказу, а не признак в справочнике. Недельный ЭСМ-2 при этом не изменился ничем — у машины, которой он положен, за день бывает две бумаги, и лишнюю аннулируют вручную"},
    {"kind":"feature","text":"Пачка делает всё, что может, и построчно рассказывает, чего не смогла: день уже стоит в рейсе, рейс заморожен выданным листом, у машины на эту дату два рейса, в бланке кончились строки задания, прошедший день без права. Такие дни пропускаются с причиной, а не роняют всю работу"},
    {"kind":"improvement","text":"За одно нажатие проходит до 50 дней — столько же листов печатается одной пачкой. Заказ длиннее не отвергается: портал говорит, сколько дней ушло сейчас и сколько осталось, и остаток добирают повторным нажатием"},
    {"kind":"fix","text":"У машины, которая за день закрыта и недельным ЭСМ-2, и дневным 4-П, показания теперь ждут один раз, а не дважды: гараж перестал показывать такую технику несдавшей каждый день, а утренняя сводка «Техника на объектах» — показывать один заказ двумя строками"},
    {"kind":"fix","text":"Окно возврата заявки в «Новую» больше не предлагает откат там, где сервер его запретит: выписанный дневной лист виден порталу до нажатия, а не после набранной причины"}
  ]'::jsonb
);
